import type { DrawnRecord } from "../drawn";

const MEDIEVAL = [
  {"id":"med:templar-baucent","group":"order","name":{"en":"The Templars' banner (the baucent)","ja":"テンプル騎士団の旗（ボーセアン）"},"about":{"en":"The banner of the Knights Templar: white with a black chief, the colours Jacques de Vitry described in the 1220s.","ja":"テンプル騎士団の旗。白地に黒い上部を持ち、1220年代にジャック・ド・ヴィトリが述べた色です。"},"status":"reconstruction","dates":{"from":"1220","until":"1312"},"note":{"en":"The black and white are the source's. The sources differ on which half is black (a black chief in the text, a black lower half in the fresco) and on the red cross of the fresco, which the article says appears to be later: this drawing follows the text, and leaves out the cross. No banner of the time survives to draw from: the proportions, the shades, the width of the arms and the rectangular cloth are this package's, so the drawing is a reconstruction.","ja":"白と黒は出典のものです。出典どうしで、どちらの半分が黒かが食い違います（文章では黒い上部、壁画では黒い下半分）。壁画の赤い十字は、記事によれば後の付加とみられます。この絵は文章に従い、十字は描きません。当時の旗は残っていないため、縦横の比、色合い、腕の太さ、長方形の布はこのパッケージのもので、この絵は復元です。"},"source":{"title":"Beauseant, Wikipedia","url":"https://en.wikipedia.org/wiki/Beauseant","kind":"encyclopedia","read":"2026-11-24","says":"Says 13th-century sources describe a white gonfanon with a black chief (argent a chief sable), names Jacques de Vitry (1220s) and Matthew Paris (c. 1250 to 1259), and says a fresco at San Bevignate (c. 1290) shows the banner with the upper half white and the lower half black and a red cross."},"svg":"<svg data-hata-med=\"templar-baucent\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 400 300\"><path fill=\"#f7f4ea\" d=\"M0 0h400v300h-400z\"/><path fill=\"#16161a\" d=\"M0 0h400v100h-400z\"/></svg>"},
  {"id":"med:red-cross","group":"cross","name":{"en":"The red cross on white (St George's Cross)","ja":"白地に赤十字（聖ジョージ十字）"},"about":{"en":"A red cross on white: the crusaders' sign from about 1190, the flag of Genoa from at least 1218, and England's flag, later tied to Saint George.","ja":"白地に赤い十字。1190年ごろから十字軍のしるしとなり、ジェノヴァの旗として遅くとも1218年から使われ、のちに聖ジョージと結び付いたイングランドの旗です。"},"status":"reconstruction","dates":{"from":"1218","until":null},"note":{"en":"The design and the date of 1218 are the source's; the 1190 grant is a tradition and is not drawn as a fact. No banner of the time survives to draw from: the proportions, the shades, the width of the arms and the rectangular cloth are this package's, so the drawing is a reconstruction.","ja":"意匠と1218年という年は出典のものです。1190年の許可は伝承で、事実としては描きません。当時の旗は残っていないため、縦横の比、色合い、腕の太さ、長方形の布はこのパッケージのもので、この絵は復元です。"},"source":{"title":"Saint George's Cross, Wikipedia","url":"https://en.wikipedia.org/wiki/Saint_George%27s_Cross","kind":"encyclopedia","read":"2026-11-24","says":"Says the Genoese annals show a plain red-cross flag from at least 1218 (and a flag of Saint George and the dragon in 1198), that the plain red on white became a recognisable crusaders' symbol from about 1190, and that the story of Richard I buying the right to the flag in 1190 is a tradition the page cannot confirm."},"svg":"<svg data-hata-med=\"red-cross\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 400 300\"><path fill=\"#f7f4ea\" d=\"M0 0h400v300h-400z\"/><path fill=\"#c8102e\" d=\"M170 0h60v300h-60zM0 120h400v60h-400z\"/></svg>"},
  {"id":"med:gelre-denmark","group":"kingdom","name":{"en":"Denmark's banner in the Gelre Armorial","ja":"ゲルレ紋章集のデンマークの旗"},"about":{"en":"A white cross on red, the banner of \"die coninc van denmarke\" on folio 55v of the Gelre Armorial, compiled before 1396: the earliest known coloured picture of the Dannebrog.","ja":"赤地に白い十字。1396年より前に編まれたゲルレ紋章集の55葉裏にある「デンマーク王」の旗で、ダンネブロの現存する最古の彩色画とされます。"},"status":"reconstruction","dates":null,"note":{"en":"The white cross on red and the date are the source's; the page does not describe the cross's proportions or the cloth's shape, so the arms' width and the cross's place (nearer the hoist, as in the Dannebrog today) are this package's. No banner of the time survives to draw from: the proportions, the shades, the width of the arms and the rectangular cloth are this package's, so the drawing is a reconstruction.","ja":"赤地に白い十字と年代は出典のものです。出典は十字の寸法も布の形も述べないため、腕の太さと十字の位置（今のダンネブロと同じく掲揚側寄り）はこのパッケージのものです。当時の旗は残っていないため、縦横の比、色合い、腕の太さ、長方形の布はこのパッケージのもので、この絵は復元です。"},"source":{"title":"Gelre Armorial, Wikipedia","url":"https://en.wikipedia.org/wiki/Gelre_Armorial","kind":"encyclopedia","read":"2026-11-24","says":"Says the armorial was compiled before 1396 by Claes Heinenzoon (fl. 1345 to 1414), that folio 55v shows a lance tip with a banner displaying a white cross on red, labelled \"die coninc van denmarke\", and that it is the earliest known coloured image of the Dannebrog."},"svg":"<svg data-hata-med=\"gelre-denmark\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 400 300\"><path fill=\"#c8102e\" d=\"M0 0h400v300h-400z\"/><path fill=\"#f7f4ea\" d=\"M120 0h60v300h-60zM0 120h400v60h-400z\"/></svg>"},
  {"id":"med:aragon-pallets","group":"kingdom","name":{"en":"The arms of Aragon","ja":"アラゴンの紋章"},"about":{"en":"Gold with four red bars, here as a banner of nine vertical stripes: the arms of Aragon, whose earliest undisputed material evidence is the seal of Alfonso II of 1159.","ja":"金地に4本の赤い帯。ここでは縦の9本の縞の旗として描きます。アラゴンの紋章で、争いのない最古の物証は1159年のアルフォンソ2世の印章です。"},"status":"reconstruction","dates":{"from":"1159","until":null},"note":{"en":"The gold and red and the four bars (vertical on the flag) are the source's, dated by the seal of 1159, whose tinctures a seal does not show: they are the blazon's. The ratio of 3 to 2 and the shades are this package's. The legend of the bars drawn by Charles the Bald is not drawn as a fact. No banner of the time survives to draw from: the proportions, the shades, the width of the arms and the rectangular cloth are this package's, so the drawing is a reconstruction.","ja":"金と赤、4本の帯（旗では縦）は出典のもので、1159年の印章で年代が示されます。印章に色は出ないため、色は紋章記述のものです。3対2の比と色合いはこのパッケージのものです。カール禿頭王が帯を描いたという伝説は、事実としては描きません。当時の旗は残っていないため、縦横の比、色合い、腕の太さ、長方形の布はこのパッケージのもので、この絵は復元です。"},"source":{"title":"Flag of Aragon, Wikipedia","url":"https://en.wikipedia.org/wiki/Flag_of_Aragon","kind":"encyclopedia","read":"2026-11-24","says":"Says the earliest undisputed material evidence of the arms is a royal seal of Alfonso II of Aragon (1159), that an equestrian seal of Ramon Berenguer IV (c. 1150) shows a paled shield with no tinctures, and gives the blazon as Or, four bars Gules."},"svg":"<svg data-hata-med=\"aragon-pallets\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 360 240\"><path fill=\"#fcd116\" d=\"M0 0h360v240h-360z\"/><path fill=\"#c8102e\" d=\"M40 0h40v240h-40zM120 0h40v240h-40zM200 0h40v240h-40zM280 0h40v240h-40z\"/></svg>"},
  {"id":"med:scotland-saltire","group":"cross","name":{"en":"The saltire of Scotland","ja":"スコットランドのサルタイア"},"about":{"en":"A white saltire (St Andrew's Cross) on blue, first recorded as a naval flag in 1507, for the carrack Great Michael.","ja":"青地に白い斜め十字（聖アンドリュー十字）。1507年に大型帆船グレート・マイケル号の旗として記録されたのが最初です。"},"status":"reconstruction","dates":{"from":"1507","until":null},"note":{"en":"The white saltire on blue and the date of 1507 are the source's, and the bars are drawn a fifth of the height wide, within the range the source gives. It is the latest banner here, at the edge of the Middle Ages: the 1286 seal and the 1385 order show the saltire as a sign, not as a banner. No banner of the time survives to draw from: the proportions, the shades, the width of the arms and the rectangular cloth are this package's, so the drawing is a reconstruction.","ja":"青地に白い斜め十字と1507年は出典のものです。帯は、出典の示す範囲内で、縦の5分の1の太さに描きます。ここにあるなかで最も新しく、中世の終わりに当たります。1286年の印章と1385年の命令が示すのは、旗ではなく、しるしとしての斜め十字です。当時の旗は残っていないため、縦横の比、色合い、腕の太さ、長方形の布はこのパッケージのもので、この絵は復元です。"},"source":{"title":"Flag of Scotland, Wikipedia","url":"https://en.wikipedia.org/wiki/Flag_of_Scotland","kind":"encyclopedia","read":"2026-11-24","says":"Says the saltire as a naval flag on blue is recorded for 1507 (the Treasurer's accounts, for the carrack Great Michael), that the white saltire on blue is first shown in 1542 in Lindsay's armorial, that a seal of the Guardians of Scotland of 1286 shows Saint Andrew on a saltire cross, and that the Parliament of Scotland in 1385 ordered a white St Andrew's Cross for soldiers; it gives the saltire's width as a third to a fifth of the field."},"svg":"<svg data-hata-med=\"scotland-saltire\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 300 180\"><path fill=\"#0a4a9c\" d=\"M0 0h300v180h-300z\"/><path fill=\"#f7f4ea\" d=\"M0 180L0 162L270 0L300 0L300 18L30 180zM0 0L30 0L300 162L300 180L270 180L0 18z\"/></svg>"},
  {"id":"med:hospitaller-cross","group":"order","name":{"en":"The Hospitallers' white cross on red","ja":"聖ヨハネ騎士団の赤地に白十字"},"about":{"en":"A white cross on red, the arms the Order of St John is said to have had from Pope Innocent II in 1130, and the cross of the red surcoat the Hospitallers wore in war from 1248.","ja":"赤地に白い十字。聖ヨハネ騎士団が1130年に教皇インノケンティウス2世から授かったとされる紋章で、1248年から戦場で着た赤い上着の十字です。"},"status":"reconstruction","dates":{"from":"1130","until":null},"note":{"en":"The white cross on red and the two dates are the source's, which names the arms and the dress and no banner; that the banner bore the same cross is this package's reading. The page names no document for the grant of 1130. No banner of the time survives to draw from: the proportions, the shades, the width of the arms and the rectangular cloth are this package's, so the drawing is a reconstruction.","ja":"赤地に白い十字と2つの年は出典のものです。出典が挙げるのは紋章と軍装で、旗には触れていません。旗が同じ十字を掲げたというのは、このパッケージの読み方です。1130年の授与について、出典は文書を挙げていません。当時の旗は残っていないため、縦横の比、色合い、腕の太さ、長方形の布はこのパッケージのもので、この絵は復元です。"},"source":{"title":"Knights Hospitaller, Wikipedia","url":"https://en.wikipedia.org/wiki/Knights_Hospitaller","kind":"encyclopedia","read":"2026-11-24","says":"Says Pope Innocent II gave the order its coat of arms, a plain silver cross in a field of red, to tell them from the Templars (1130; no document is named), and that in 1248 Pope Innocent IV approved a military dress of a red surcoat with a white cross."},"svg":"<svg data-hata-med=\"hospitaller-cross\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 400 300\"><path fill=\"#c8102e\" d=\"M0 0h400v300h-400z\"/><path fill=\"#f7f4ea\" d=\"M170 0h60v300h-60zM0 120h400v60h-400z\"/></svg>"},
] as const satisfies readonly DrawnRecord[];

export { MEDIEVAL };
